sys_uib_toolbox_component.component_config:
{
    "sn_embeddables": {
        "component_code_snippet": "/* Uncomment this code for the default behaviour of the Case View component.\n\n\t// Get the record id and table from the current URL for a standard case.\n\t// Optionally, get playbook experience ID, playbook context ID, stage context ID,\n\t// and activity context ID for playbook case.\n\tconst currentURL = new URL(window.location.href);\n\tconst urlParams = new URLSearchParams(currentURL.search);\n\tconst tableName = urlParams.get('emb_table');\n\tconst sysRecordId = urlParams.get('emb_recordid');\n\tconst playbookExperience = urlParams.get('emb_playbook_experience');\n\tconst playbookContextId = urlParams.get('emb_playbook_context_id');\n\tconst stageContextId = urlParams.get('emb_stage_context_id');\n\tconst activityContextId = urlParams.get('emb_activity_context_id');\n\n\t// Update the sysId and table properties of the componentProperties object.\n\t// Optionally, update the playbook experience ID, playbook context ID,\n\t// stage context ID, and activity context ID for the playbook case view as well.\n\tsetProperties(snCustomEmbedxB2bLoanApplicationTask,{\n\t\ttable:tableName,\n\t\tsysId:sysRecordId,\n\t\tplaybookExperience:playbookExperience,\n\t\tselectedPlaybookContextId:playbookContextId,\n\t\tselectedStageContextId:stageContextId,\n\t\tselectedActivityContextId:activityContextId\n\t});\n\t*/",
        "embed_code": {
            "hide_events": [
                "SN_EMBEDX_CASE_VIEW#ACTIVITY_SELECTED",
                "SN_EMBEDX_CASE_VIEW#STAGE_SELECTED",
                "SN_EMBEDX_CASE_VIEW#ACTIVITY_STATE_CHANGED",
                "SN_EMBEDX_CASE_VIEW#UPDATE_SELECTION",
                "SN_EMBEDX_CASE_VIEW#FILTER_SELECTED",
                "SN_EMBEDX_CASE_VIEW#FILTER_OPTION_SELECTED",
                "SN_EMBEDX_CASE_VIEW#PLAYBOOK_EXPANDED",
                "SN_EMBEDX_CASE_VIEW#OPEN_RECORD",
                "SN_EMBEDX_CASE_VIEW#USER_INTERACTION",
                "SN_EMBEDX_CASE_VIEW#OPEN_LIST"
            ],
            "hide_properties": [
                "playbookExperience"
            ]
        },
        "overrided_props": {
            "hideErrors": false
        },
        "refresh_preview_on_prop_change": [
            "actionConfigurationId",
            "hideActivity",
            "hideAttachments",
            "hideAllRelatedLists",
            "showCustomTab",
            "tableViewForRelatedList",
            "visibleHorizontalPlaybookStages"
        ],
        "static_preview_image": null
    }
}

sys_uib_toolbox_component.scripted_config_policy:
// eslint-disable-next-line no-unused-vars
            function configureProps(obj) {
                const { trigger, api, properties } = obj;

                const toggleVisibility = (property, value) => {
                    api.updateVisibility(property, value);
                };

                const updatePlaybookPropertiesVisibility = () => {
                    const playbookProperties = [
                        { property: 'playbookExperience', value: !properties.hidePlaybookProcessTab },
                        { property: 'playbookStageOrientation', value: !properties.hidePlaybookProcessTab && !properties.hidePlaybookStages },
                        { property: 'visibleHorizontalPlaybookStages', value: !properties.hidePlaybookProcessTab && !properties.hidePlaybookStages && properties.playbookStageOrientation === 'horizontal' },
                        { property: 'playbookActivityViewMode', value: !properties.hidePlaybookProcessTab },
						{ property: 'hidePlaybookStages', value: !properties.hidePlaybookProcessTab }
                    ];
                    playbookProperties.forEach(({ property, value }) => {
                        toggleVisibility(property, value);
                    });
                };

                const updateTriggerSpecificVisibility = () => {
                    switch (trigger) {
                        case 'hideActions':
                            toggleVisibility('actionConfigurationId', !properties.hideActions);
                            break;
                        case 'hideAllRelatedLists':
                            toggleVisibility('tableViewForRelatedList', !properties.hideAllRelatedLists);
                            break;
                        case 'hideActivity':
                            toggleVisibility('enableRichText', !properties.hideActivity);
                            break;
                        default:
                            break;
                    }
                };

                if(trigger)
                    updateTriggerSpecificVisibility();
                updatePlaybookPropertiesVisibility();
        }
